using YoWidgets.Core;

var failures = 0;
var total = 0;
void Test(string name, Action run) { total++; try { run(); Console.WriteLine("PASS " + name); } catch (Exception e) { failures++; Console.WriteLine("FAIL " + name + ": " + e.Message); } }
void Eq<T>(T expected, T actual) { if (expected is double a && actual is double b && Math.Abs(a - b) < .000001) return; if (!EqualityComparer<T>.Default.Equals(expected, actual)) throw new Exception($"Expected {expected}, got {actual}"); }
Test("offscreen position returns to negative-coordinate display", () => { var p = Placement.Clamp(5000, 900, 300, 200, new(-1920, 0, 1920, 1080)); Eq(-300d, p.X); Eq(880d, p.Y); });
Test("oversized widget anchors at work area origin", () => { var p = Placement.Clamp(-400, 20, 2500, 1400, new(100, 100, 1920, 1080)); Eq(100d, p.X); Eq(100d, p.Y); });
Test("cleanup rejects sibling with same prefix", () => Eq(false, OwnedPaths.IsInside(@"C:\Users\A\YoWidgets", @"C:\Users\A\YoWidgets-old\photo.jpg")));
Test("cleanup rejects root itself", () => Eq(false, OwnedPaths.IsInside(@"C:\Users\A\YoWidgets", @"C:\Users\A\YoWidgets")));
Test("cleanup accepts child", () => Eq(true, OwnedPaths.IsInside(@"C:\Users\A\YoWidgets", @"C:\Users\A\YoWidgets\cache\art.png")));
Test("lyrics parses repeated timestamps and sorts", () => { var l = Lyrics.Parse("[00:09.50][00:19.50]Again\n[00:01.20]First\n[ar:Example]"); Eq(3, l.Count); Eq(1.2, l[0].Seconds); Eq("Again", l[2].Text); });
Test("generation gate rejects response after suspension", () => { var g = new WorkGate(); var v = g.Version; g.Suspend(); Eq(false, g.CanApply(v)); g.Resume(); Eq(false, g.CanApply(v)); Eq(true, g.CanApply(g.Version)); });
Test("invalid numeric widget positions are normalized", () => { var w = new WidgetState { X = double.NaN, Y = double.PositiveInfinity }; var s = new AppSettings { Widgets = [w] }; s.Normalize(); Eq(80d, w.X); Eq(80d, w.Y); });
Test("corrupt settings recover without loss of backup", () => { var d = Path.Combine(Path.GetTempPath(), "YoWidgetsTest-" + Guid.NewGuid()); Directory.CreateDirectory(d); try { var store = new SettingsStore(Path.Combine(d, "settings.json")); store.Save(new AppSettings { City = "Lviv" }); File.WriteAllText(store.Path, "broken"); Eq("Lviv", store.Load().City); Eq(true, File.Exists(store.Path + ".corrupt")); } finally { Directory.Delete(d, true); } });
Test("fit wallpaper has letterbox offset", () => { var r = WallpaperLayout.Calculate(1920, 1080, new(0, 0, 1000, 1000), "Fit"); Eq(1000d, r.Width); Eq(562.5, r.Height); Eq(218.75, r.Y); });
Test("inactive or paused widgets request no fast timer", () => { Eq(60, ActivityPolicy.Seconds(false, false, false, false)); Eq(1, ActivityPolicy.Seconds(true, false, false, false)); Eq(0, ActivityPolicy.Seconds(true, true, true, true)); });
Test("duplicate widget ids cannot lose a window during cleanup", () => { var s = new AppSettings { Widgets = [new() { Id = "same", Kind = "clock" }, new() { Id = "same", Kind = "music" }] }; s.Normalize(); Eq(2, s.Widgets.Select(x => x.Id).Distinct().Count()); });
Test("rollback preserves external changes", () => Eq(false, RollbackPolicy.CanRestore("speaker", "speaker", 70, 45)));
Test("rollback refuses a replacement device", () => Eq(false, RollbackPolicy.CanRestore("old", "new", 45, 45)));
Test("rollback tolerates device rounding", () => Eq(true, RollbackPolicy.CanRestore("speaker", "speaker", 44.8, 45)));
Test("disable all clears private integration opt-ins", () => { var s = new AppSettings { NotificationsEnabled = true, LyricsEnabled = true }; s.DisableIntegrations(); Eq(false, s.NotificationsEnabled); Eq(false, s.LyricsEnabled); });
Test("fallback weather parses numeric strings and forecast", () => { var r = WeatherFallback.Parse("""{"current_condition":[{"temp_C":"12","weatherDesc":[{"value":"Cloudy"}],"lang_ru":[{"value":"Облачно"}]}],"weather":[{"date":"2026-10-19","maxtempC":"14","mintempC":"8","hourly":[{"time":"0","tempC":"9"},{"time":"300","tempC":"10"}]}]}"""); Eq(12d, r.Temperature); Eq(8d, r.Low); Eq("Cloudy", r.Condition); Eq("Mon", r.Days[0].Time); Eq("03:00", r.Hours[1].Time); });
Test("failed retry preserves confirmed rollback baseline", () => { var a = ChangeJournal.Advance(null, "brightness", "panel", 30, 40, "prepared"); a = ChangeJournal.Advance(a, "brightness", "panel", 30, 40, "applied"); a = ChangeJournal.Advance(a, "brightness", "panel", 40, 50, "prepared"); Eq(40d, a.Last); Eq("applied", a.Stage); a = ChangeJournal.Advance(a, "brightness", "panel", 40, 60, "prepared"); a = ChangeJournal.Advance(a, "brightness", "panel", 40, 60, "applied"); Eq(30d, a.Original); Eq(60d, a.Last); Eq<double?>(null, a.Pending); });
Test("unconfirmed first attempt cannot claim a confirmed rollback", () => { var a = ChangeJournal.Advance(null, "volume", "speaker", 30, 40, "prepared"); Eq("prepared", a.Stage); a = ChangeJournal.Advance(a, "volume", "speaker", 35, 50, "prepared"); a = ChangeJournal.Advance(a, "volume", "speaker", 35, 50, "applied"); Eq(35d, a.Original); });
Test("fallback hourly forecast skips past city-local hours", () => { var r = WeatherFallback.Parse("""{"current_condition":[{"temp_C":"12","localObsDateTime":"2026-10-19 06:30 PM","weatherDesc":[{"value":"Cloudy"}]}],"weather":[{"date":"2026-10-19","maxtempC":"14","mintempC":"8","hourly":[{"time":"0","tempC":"9"},{"time":"1800","tempC":"10"},{"time":"2100","tempC":"11"}]},{"date":"2026-10-20","maxtempC":"15","mintempC":"8","hourly":[{"time":"0","tempC":"8"}]}]}"""); Eq("21:00", r.Hours[0].Time); Eq("00:00", r.Hours[1].Time); });
Test("legacy desktop parent setting is migrated off", () => { var s = new AppSettings { DesktopMode = true }; s.Normalize(); Eq(false, s.DesktopMode); });
Test("center placement supports negative-coordinate monitor", () => { var p = Placement.Center(400, 200, new(-1920, 0, 1920, 1040)); Eq(-1160d, p.X); Eq(420d, p.Y); });
Test("wallpaper crop retains only widget source region", () => { var crop = WallpaperCrop.Calculate(3840, 2160, new(0, 0, 1920, 1080), new(100, 100, 400, 200)); Eq(198d, crop.X); Eq(804d, crop.Width); Eq(404d, crop.Height); });
Test("wallpaper crop handles Fit letterbox without invalid bitmap", () => { var crop = WallpaperCrop.Calculate(3840, 2160, new(0, 250, 1000, 562.5), new(100, 0, 100, 100)); Eq(0d, crop.Height); });
Test("center reset separates two widget windows", () => { var a = Placement.CenterGrid(498, 170, new(0, 0, 1920, 1006), 0, 2, 498, 260); var b = Placement.CenterGrid(498, 260, new(0, 0, 1920, 1006), 1, 2, 498, 260); Eq(450d, a.X); Eq(972d, b.X); Eq(true, a.X + 498 < b.X); });
Test("moving backdrop uses physical monitor coordinates including negatives", () => { var v = BackdropViewport.For(new(-1800, 100, 400, 200), new(-1920, 0, 1920, 1080)); Eq(.0625, v.X); Eq(400d / 1920, v.Width); });
Test("artwork keeps track image without requesting logo", () => { var fallbackCalled = false; var r = ArtworkSelection.FirstAsync(() => Task.FromResult<string?>("album"), () => { fallbackCalled = true; return Task.FromResult<string?>("logo"); }).GetAwaiter().GetResult(); Eq("album", r.Image); Eq(false, fallbackCalled); });
Test("broken track cover falls back to website logo", () => { var r = ArtworkSelection.FirstAsync<string>(() => throw new IOException("corrupt thumbnail"), () => Task.FromResult<string?>("site")).GetAwaiter().GetResult(); Eq("site", r.Image); Eq(false, r.Primary); });
Test("both artwork sources absent leave no placeholder", () => { var r = ArtworkSelection.FirstAsync<string>(() => Task.FromResult<string?>(null), () => throw new IOException("offline")).GetAwaiter().GetResult(); Eq<string?>(null, r.Image); });
Test("artwork cancellation cannot start fallback network work", () => { var fallback = false; try { ArtworkSelection.FirstAsync<string>(() => throw new OperationCanceledException(), () => { fallback = true; return Task.FromResult<string?>("wrong"); }).GetAwaiter().GetResult(); throw new Exception("Cancellation lost"); } catch (OperationCanceledException) { } Eq(false, fallback); });
Test("website fallback identifies only supported public origins", () => { Eq("https://www.tiktok.com/favicon.ico", ArtworkPolicy.WebsiteIcon("Chrome", "Rickky | TikTok")); Eq<string?>(null, ArtworkPolicy.WebsiteIcon("Chrome", "Unknown song")); });
Test("media timeline compensates source update age instead of lagging", () => { var c = new MediaClock(); var now = DateTimeOffset.UtcNow; c.Apply(new(12, 0, 233, now.AddSeconds(-16)), true, 1, now, 100); Eq(28d, c.Position(100)); });
Test("repeated stale snapshots cannot rewind playback", () => { var c = new MediaClock(); var now = DateTimeOffset.UtcNow; var t = new MediaTimeline(12, 0, 233, now); c.Apply(t, true, 1, now, 100); c.Apply(t, true, 1, now.AddSeconds(5), 105); Eq(17d, c.Position(105)); });
Test("pause freezes projected position and resume excludes paused time", () => { var c = new MediaClock(); var now = DateTimeOffset.UtcNow; var t = new MediaTimeline(12, 0, 233, now); c.Apply(t, true, 1, now, 100); c.Apply(t, false, 1, now.AddSeconds(5), 105); Eq(17d, c.Position(130)); c.Apply(t, true, 1, now.AddSeconds(25), 125); Eq(20d, c.Position(128)); });
Test("fresh seek snapshot may move backwards", () => { var c = new MediaClock(); var now = DateTimeOffset.UtcNow; c.Apply(new(100, 0, 233, now), true, 1, now, 100); c.Apply(new(20, 0, 233, now.AddSeconds(1)), true, 1, now.AddSeconds(1), 101); Eq(20d, c.Position(101)); });
Test("media rate and nonzero timeline origin are respected", () => { var c = new MediaClock(); var now = DateTimeOffset.UtcNow; c.Apply(new(50, 30, 230, now.AddSeconds(-3)), true, 2, now, 100); Eq(26d, c.Position(100)); Eq(30d, c.Position(102)); Eq(200d, c.Duration); });
Test("future source timestamp cannot subtract playback time", () => { var c = new MediaClock(); var now = DateTimeOffset.UtcNow; c.Apply(new(12, 0, 233, now.AddMinutes(2)), true, 1, now, 100); Eq(12d, c.Position(100)); });
Test("track reset clears duration and stale position", () => { var c = new MediaClock(); var now = DateTimeOffset.UtcNow; c.Apply(new(100, 0, 233, now), true, 1, now, 100); c.Reset(); Eq(0d, c.Position(500)); });
Test("video sites never expose queue shuffle or repeat", () => { Eq((false,false), MediaCapabilities.QueueControls(true, false, true, true, "Chrome", "A video | YouTube")); Eq((false,false), MediaCapabilities.QueueControls(true, false, true, true, "TikTok")); });
Test("music exposes only capabilities actually provided by source", () => { Eq((true,true), MediaCapabilities.QueueControls(true, false, true, true, "Spotify")); Eq((false,false), MediaCapabilities.QueueControls(true, false, false, false, "SoundCloud")); Eq((false,true), MediaCapabilities.QueueControls(true, false, false, true, "Spotify")); });
Test("closing or video playback retracts queue controls", () => { Eq((false,false), MediaCapabilities.QueueControls(false, false, true, true, "Spotify")); Eq((false,false), MediaCapabilities.QueueControls(true, true, true, true, "player")); });
Test("new widgets belong to Liquid Glass", () => Eq("liquid", new WidgetState().Pack));
Test("contrast chooses dark text on white and white text on dark", () => { Eq(true, ContrastPolicy.DarkInk(ContrastPolicy.Luminance(255,255,255), null)); Eq(false, ContrastPolicy.DarkInk(ContrastPolicy.Luminance(0,0,0), null)); });
Test("contrast hysteresis prevents flicker around mid tones", () => { Eq(false, ContrastPolicy.DarkInk(.25, false)); Eq(true, ContrastPolicy.DarkInk(.25, true)); Eq(false, ContrastPolicy.DarkInk(double.NaN, false)); });
Test("mixed bright-dark backgrounds do not retain invisible dark ink", () => { Eq(false, ContrastPolicy.DarkInk(ContrastPolicy.MergeMargins([.01,.8,.01,.8]), true)); Eq(true, ContrastPolicy.DarkInk(ContrastPolicy.MergeMargins([.9,.95,.92,1]), false)); });
Test("minute clock updates at the next wall-clock minute", () => { var now = new DateTime(2026,10,19,23,55,48); Eq(12.02, ActivityPolicy.NextDelay(60, true, now)); Eq(1d, ActivityPolicy.NextDelay(1, true, now)); Eq(60d, ActivityPolicy.NextDelay(60, false, now)); });
Test("unknown collection keeps its content key but selects only a safe native renderer", () => { var w = new WidgetState { Pack = "external-dll" }; var s = new AppSettings { Widgets = [w] }; s.Normalize(); Eq("external-dll", w.Pack); Eq("liquid", WidgetPacks.Get(w.Pack).Id); w.Pack = "../unsafe"; s.Normalize(); Eq("liquid", w.Pack); });
Test("legacy global glass setting cannot restore wallpaper rendering", () => { var s = System.Text.Json.JsonSerializer.Deserialize<AppSettings>("""{"MaterialPackage":"glass","Widgets":[{"Id":"saved","Kind":"clock","Enabled":true,"X":973,"Y":157}]}""")!; s.Normalize(); var w = s.Widgets.Single(); Eq("liquid", w.Pack); Eq("saved", w.Id); Eq(973d, w.X); Eq(157d, w.Y); Eq(true, w.Enabled); });
Test("both packs survive a settings roundtrip independently", () => { var s = new AppSettings { Widgets = [new() { Kind = "music", Pack = "glass", Enabled = true },new() { Kind = "music", Pack = "liquid", Enabled = false }] }; var restored = System.Text.Json.JsonSerializer.Deserialize<AppSettings>(System.Text.Json.JsonSerializer.Serialize(s))!; restored.Normalize(); Eq("glass", restored.Widgets[0].Pack); Eq(true, restored.Widgets[0].Enabled); Eq("liquid", restored.Widgets[1].Pack); Eq(false, restored.Widgets[1].Enabled); });
Test("saved settings no longer expose a global material switch", () => Eq(false, System.Text.Json.JsonSerializer.Serialize(new AppSettings()).Contains("MaterialPackage")));
Test("packs use subtle live blur without a wallpaper source", () => { Eq(2, WidgetPacks.All.Count); Eq(true, WidgetPacks.Get("glass").Blur <= 3f); Eq(true, WidgetPacks.Get("liquid").Blur <= 3f); Eq(true, WidgetPacks.Get("liquid").InteractionBlur > WidgetPacks.Get("liquid").Blur); });
Test("a music track mentioning a video brand is not a video source", () => { Eq((true,true), MediaCapabilities.QueueControls(true, false, true, true, "SpotifyAB.SpotifyMusic", "A TikTok remix | YouTube")); Eq((true,true), MediaCapabilities.QueueControls(true, false, true, true, "Chrome", "TikTok remix", "Musician")); });
AssistantChecks.Run(Test);
AssistantLayoutChecks.Run(Test);
LyricChecks.Run(Test);
BridgeChecks.Run(Test);
BridgeTransportChecks.Run(Test);
Console.WriteLine($"RESULT: {total - failures}/{total} passed");
return failures == 0 ? 0 : 1;
